-- TIBOX Compliance — importación del catálogo creado por Paula en SharePoint
-- Ejecutar DESPUÉS de 20260826120000_initial_mvp.sql
-- Carga el contenido funcional al tenant de demostración `cliente-demo`.
-- Los KPIs de `Resumen Ejecutivo.csv` NO se persisten porque eran valores estáticos
-- y no coinciden con los estados exportados; la aplicación los calcula dinámicamente.

begin;

do $$
declare
  v_org uuid;
begin
  values ('Cliente Demo', 'cliente-demo', 'active', false)
  on conflict (slug) do update set name = excluded.name, status = 'active';

  select id into v_org from public.organizations where slug = 'cliente-demo';

  -- Reemplazar solo el catálogo/demo funcional de esta organización.
  delete from public.compliance_modules where organization_id = v_org;
  delete from public.security_categories where organization_id = v_org;

  -- 9 módulos definidos en SharePoint.

  -- 24 obligaciones/evidencias solicitadas.

  -- 7 categorías del assessment técnico.

  -- 58 controles de seguridad. Los títulos repetidos se mantienen porque pertenecen a categorías distintas.







  values (v_org, null, 'catalog.imported', 'organization', jsonb_build_object(
    'source', 'Paula SharePoint export',
    'modules', 9,
    'obligations', 24,
    'security_categories', 7,
    'security_controls', 58,
    'note', 'Adjuntos no incluidos: los CSV solo contienen contador de adjuntos.'
  ));
end $$;

commit;
